def parse_kb():
    entries = []
    for line in KB_TEXT.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = [p.strip() for p in line.split("|")]
        assert len(parts) == 5, line
        name, plural, article, answer, more = parts
        entries.append(dict(
            name=name,
            plural=None if plural == "-" else plural,
            article=None if article == "-" else article,
            answer=answer,
            more=more,
        ))
    return entries


